#!/usr/bin/env python3
"""PreToolUse hook on the Agent tool: subagents may only be started with a brief generated by
`python3 tools/mae.py brief <task>`, passed verbatim. This stops the orchestrator from
paraphrasing results, leaking the designer's reasoning into verification prompts, or
dispatching work the workflow did not schedule.
"""
import json
import os
import re
import sys

MAX_EXTRA_CHARS = 400


def deny(msg: str) -> None:
    print(msg, file=sys.stderr)
    sys.exit(2)


def main() -> None:
    data = json.load(sys.stdin)
    root = os.environ.get("CLAUDE_PROJECT_DIR") or data.get("cwd") or os.getcwd()
    inp = data.get("tool_input", {}) or {}
    prompt = inp.get("prompt", "") or ""
    target = inp.get("subagent_type", "")
    caller = data.get("agent_type") or "ic-orchestrator"
    if caller != "ic-orchestrator":
        deny(f"[{caller}] only the orchestrator may start subagents.")
    m = re.search(r"BRIEF-ID: (\S+)", prompt)
    if not m:
        deny("Start subagents only with the output of `python3 tools/mae.py brief <task>` as the prompt (no BRIEF-ID found).")
    path = os.path.join(root, ".mae", "briefs", m.group(1) + ".md")
    if not os.path.isfile(path):
        deny(f"Unknown BRIEF-ID {m.group(1)}: regenerate it with `python3 tools/mae.py brief <task>`.")
    brief = open(path).read().strip()
    if brief not in prompt:
        deny("The brief was modified. Pass the output of `mae brief` verbatim; do not summarise or add results.")
    if len(prompt) - len(brief) > MAX_EXTRA_CHARS:
        deny(f"Prompt adds {len(prompt) - len(brief)} characters to the brief (max {MAX_EXTRA_CHARS}). "
             "Context for subagents comes only from the brief.")
    role = re.search(r"^ROLE: (\S+)", brief, re.M).group(1)
    if target != role:
        deny(f"Brief {m.group(1)} is for '{role}', not '{target}'.")
    sys.exit(0)


if __name__ == "__main__":
    main()
